 const tick=()=>{const b=$('#resend-code');if(!b){clearInterval(authTimer);return}const seconds=Math.max(0,Math.ceil((resendAt-Date.now())/1000));b.disabled=authBusy||seconds>0;b.textContent=seconds?`${seconds}秒后可重发`:'重新发送验证码'};clearInterval(authTimer);tick();authTimer=setInterval(tick,1000);
