async function logout(){if(dirty&&!await ensureSaved()){if(!confirm('部分修改尚未保存。确定退出并放弃这些未保存修改吗？可先取消并导出。'))return}await api('/api/auth/logout',{method:'POST',body:{}});clearPrivateState();history.replaceState(null,'','#account');renderAuth();syncView()}
function downloadJSON(value,filename){const blob=new Blob([JSON.stringify(value,null,2)],{type:'application/json'}),url=URL.createObjectURL(blob),link=document.createElement('a');link.href=url;link.download=filename;link.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}
function readLegacyState(){let value;try{value=JSON.parse(localStorage.getItem(KEY)||'null')}catch{return null}if(!isRecord(value))return null;const previous=state;try{state=normalizeState(value,activeChild);state.recordSchemaVersion=value.recordSchemaVersion;migrateLegacyRecords();return JSON.parse(JSON.stringify(state))}finally{state=previous}}
function renderLegacyImport(){const destinationId=activeChild?.id,destinationEpoch=contextEpoch,destinationUser=session?.user.id;const legacy=readLegacyState(),root=$('#legacy-import-preview');if(!legacy||(!Object.keys(legacy.records).length&&!Object.keys(legacy.completed).length&&!Object.keys(legacy.legacyRecords).length)){root.innerHTML='<p class="muted-note">此浏览器没有可导入的旧记录，或旧数据不可读取。源数据未被修改。</p>';return}const recordCount=Object.keys(legacy.records).length,completed=Object.values(legacy.completed).filter(Boolean).length;root.innerHTML=`<p><strong>目标孩子：${escapeHTML(activeChild?.nickname||'请先选择孩子')}</strong><br>检测到 ${recordCount} 组旧记录、${completed} 个完成标记。原始数据保留，不会清除。</p><p class="muted-note">导入只接受已开放关卡。若包含锁定活动，请先联系管理员开放；导入失败不会删除源记录。若目标已有记录，请先导出，两份资料不会在未确认时自动互相覆盖。</p><label class="import-confirm"><input id="import-consent" type="checkbox"> 我确认这些是当前孩子的记录，并同意上传到这个家庭账号。</label><button id="import-legacy" class="button outline" disabled>导入到 ${escapeHTML(activeChild?.nickname||'当前孩子')}</button><p id="import-message" class="form-message" role="status"></p>`;$('#import-consent').addEventListener('change',()=>$('#import-legacy').disabled=!$('#import-consent').checked);$('#import-legacy').addEventListener('click',()=>action($('#import-legacy'),async()=>{if(!$('#import-consent').checked||destinationId!==activeChild?.id||destinationEpoch!==contextEpoch||destinationUser!==session?.user.id)return;if(!await ensureSaved())return;if(destinationId!==activeChild?.id||destinationEpoch!==contextEpoch||destinationUser!==session?.user.id)throw new Error('儿童档案已切换，请重新选择导入目标。');if(Object.keys(state.records).length&&!confirm('当前孩子已有云端记录。请先导出备份；继续将按服务端规则合并旧记录，不允许覆盖已有不同内容。是否继续？'))return;const id=destinationId,epoch=destinationEpoch,result=await api('/api/children/'+encodeURIComponent(id)+'/import',{method:'POST',body:{revision,state:legacy,confirmed:true}});if(epoch!==contextEpoch)return;state=normalizeState(result.state,activeChild);revision=result.revision;access=result.access;dirty=false;await refreshCurriculum(epoch);renderFamilyBar();setMessage('import-message','已导入并保存到云端。浏览器里的原始记录仍然保留。')},'import-message'))}

async function renderAdmin(){
 if(session?.user?.role!=='admin')return;const epoch=contextEpoch;$('#admin-content').innerHTML=`<div class="admin-heading"><div><span class="account-kicker">ADMINISTRATION / FAMILY LAB</span><h1 id="admin-heading">管理中心</h1></div><a href="#lab" class="text-button">返回探索</a></div><div class="admin-tabs" role="group" aria-label="管理分类"><button data-admin-section="users" aria-pressed="${adminSection==='users'}">用户与关卡</button><button data-admin-section="settings" aria-pressed="${adminSection==='settings'}">注册设置</button><button data-admin-section="audit" aria-pressed="${adminSection==='audit'}">操作记录</button></div><p id="admin-message" class="form-message" role="status"></p><div id="admin-panel"><p class="account-loading">正在读取管理数据…</p></div>`;
 $$('[data-admin-section]').forEach(b=>b.addEventListener('click',()=>{adminSection=b.dataset.adminSection;renderAdmin()}));try{if(adminSection==='users')await renderAdminUsers();else if(adminSection==='settings'){const result=await api('/api/admin/settings');if(epoch===contextEpoch)renderAdminSettings(result)}else{const result=await api('/api/admin/audit?limit=50');if(epoch!==contextEpoch)return;const entries=result.events||result.audit||result.entries||[];$('#admin-panel').innerHTML=`<h2>最近的管理操作</h2><p class="muted-note">记录账号与权限变更，不展示儿童观察笔记或验证码。</p><ul class="audit-list">${entries.length?entries.map(e=>`<li><strong>${escapeHTML(e.action||e.type)}</strong><br>${escapeHTML(e.createdAt||e.at||'')} · ${escapeHTML(e.actorEmail||e.actorId||'系统')}<br>对象：${escapeHTML(e.targetId||e.target||'—')}</li>`).join(''):'<li>暂时没有管理操作记录。</li>'}</ul>`}}catch(error){if(epoch!==contextEpoch||session?.user.role!=='admin'||!$('#admin-panel'))return;setMessage('admin-message',error.message,true);$('#admin-panel').innerHTML='<button id="retry-admin" class="button outline">重试</button>';$('#retry-admin').addEventListener('click',renderAdmin)}
}
async function renderAdminUsers(query=''){
 const epoch=contextEpoch,result=await api('/api/admin/users?limit=50&offset=0&query='+encodeURIComponent(query));if(epoch!==contextEpoch||session?.user.role!=='admin')return;const users=result.users||[];
 $('#admin-heading')?.scrollIntoView({block:'start',behavior:'instant'});
 $('#admin-panel').innerHTML=`<form id="admin-search" class="admin-tools"><input id="admin-query" type="search" maxlength="254" placeholder="搜索邮箱" aria-label="搜索用户邮箱" value="${escapeHTML(query)}"><button class="button outline" type="submit">搜索</button><button id="admin-add-user" class="button primary" type="button">邀请用户</button></form><p class="muted-note">共 ${Number(result.total)||users.length} 个账号；每次显示前50条，可按邮箱搜索。停用／归档会撤销登录会话，保留可恢复记录。</p><div class="admin-table-wrap"><table class="admin-table"><thead><tr><th>家长账号</th><th>状态／角色</th><th>关卡权限</th><th>操作</th></tr></thead><tbody>${users.map(u=>`<tr><td>${escapeHTML(u.email)}${u.id===session.user.id?'<br><small>当前管理员</small>':''}</td><td><span class="status-badge ${u.status==='active'?'':'inactive'}">${escapeHTML(({active:'有效',disabled:'已停用',archived:'已归档',invited:'待验证'})[u.status]||u.status)}</span><br>${u.role==='admin'?'管理员':'家长'}</td><td>${u.unlockAll?'全部关卡':Number(u.unlockThrough)>0?'开放至第 '+Number(u.unlockThrough)+' 关':'全部锁定'}</td><td><button class="button outline" data-manage-user="${escapeHTML(u.id)}">管理</button></td></tr>`).join('')||'<tr><td colspan="4" class="admin-empty">没有匹配的账号。</td></tr>'}</tbody></table></div><div id="admin-user-detail"></div>`;
 $('#admin-search').addEventListener('submit',event=>{event.preventDefault();action($('#admin-search button'),()=>renderAdminUsers($('#admin-query').value.trim()),'admin-message')});$('#admin-add-user').addEventListener('click',()=>renderInviteUser());$$('[data-manage-user]').forEach(b=>b.addEventListener('click',()=>renderUserDetail(users.find(u=>u.id===b.dataset.manageUser))));
}
function renderInviteUser(){const root=$('#admin-user-detail');root.innerHTML='<section class="admin-detail"><h2>创建待验证的家长账号</h2><p class="muted-note">只创建待验证账号，不自动登录、不代替邮箱验证。新账号默认没有活动权限。请通知家长选择“注册家长账号”并用自己的邮箱验证。</p><form id="invite-form" class="account-form"><label>家长邮箱<input id="invite-email" type="email" required maxlength="254" autocomplete="off"></label><button id="invite-user" class="button primary" type="submit">创建待验证账号</button><p id="user-detail-message" class="form-message" role="status"></p></form></section>';$('#invite-form').addEventListener('submit',event=>{event.preventDefault();action($('#invite-user'),async()=>{await api('/api/admin/users',{method:'POST',body:{email:$('#invite-email').value.trim().toLowerCase()}});await renderAdminUsers();setMessage('admin-message','待验证账号已创建。请让家长选择“注册家长账号”完成邮箱验证。')},'user-detail-message')});scrollTo('#admin-user-detail')}
function renderUserDetail(user){
 if(!user)return;const self=user.id===session.user.id||user.status==='invited';$('#admin-user-detail').innerHTML=`<section class="admin-detail"><h2>${escapeHTML(user.email)}</h2><p class="muted-note">管理账号和活动权限；此页面不展示儿童笔记。</p><form id="user-role-form" class="account-form"><label>角色<select id="user-role" ${self?'disabled':''}><option value="parent" ${user.role==='parent'?'selected':''}>家长</option><option value="admin" ${user.role==='admin'?'selected':''}>管理员</option></select></label><label>状态<select id="user-status" ${self?'disabled':''}><option value="active" ${user.status==='active'?'selected':''}>有效</option><option value="disabled" ${user.status==='disabled'?'selected':''}>停用（可恢复）</option><option value="archived" ${user.status==='archived'?'selected':''}>归档（可恢复）</option></select></label><button id="save-user-role" class="button outline" type="submit" ${self?'disabled':''}>保存账号设置</button></form><div class="account-section"><h3>关卡权限</h3>${user.role==='admin'?'<p class="muted-note">管理员拥有全部关卡权限，不可通过此表锁定管理员。</p>':''}<form id="user-access-form" class="account-form"><label>开放范围<select id="user-access-mode"><option value="through" ${!user.unlockAll&&user.unlockThrough>0?'selected':''}>开放至指定关卡</option><option value="all" ${user.unlockAll?'selected':''}>一次解锁全部365关</option><option value="locked" ${!user.unlockAll&&!user.unlockThrough?'selected':''}>锁定全部关卡</option></select></label><label id="through-label">开放至第几关<input id="user-access-through" type="number" min="1" max="365" value="${Math.max(1,Number(user.unlockThrough)||1)}"></label><p class="muted-note">权限作用于这个家长账号下的儿童档案。锁定不删除历史记录；实际权限始终由服务器判断。</p><button id="save-user-access" class="button primary" type="submit" ${user.role==='admin'?'disabled':''}>应用关卡权限</button></form></div><p id="user-detail-message" class="form-message" role="status"></p></section>`;
 const modeChange=()=>$('#through-label').hidden=$('#user-access-mode').value!=='through';$('#user-access-mode').addEventListener('change',modeChange);modeChange();
 $('#user-role-form').addEventListener('submit',event=>{event.preventDefault();action($('#save-user-role'),async()=>{const role=$('#user-role').value,status=$('#user-status').value;if(!confirm(`确认将 ${user.email} 设置为“${role==='admin'?'管理员':'家长'} / ${status==='active'?'有效':status==='disabled'?'停用':'归档'}”？权限变化会记录到审计日志。`))return;await api('/api/admin/users/'+encodeURIComponent(user.id),{method:'PATCH',body:{role,status}});await renderAdminUsers();setMessage('admin-message','账号设置已更新。')},'user-detail-message')});
 $('#user-access-form').addEventListener('submit',event=>{event.preventDefault();action($('#save-user-access'),async()=>{const mode=$('#user-access-mode').value,through=Number($('#user-access-through').value);if(mode==='through'&&(!Number.isInteger(through)||through<1||through>365))throw new Error('请输入1至365之间的整数。');const label=mode==='all'?'解锁全部365关':mode==='locked'?'锁定全部关卡':'开放至第 '+through+' 关';if(!confirm(`确认对 ${user.email} ${label}？该操作影响此账号的儿童档案。`))return;await api('/api/admin/users/'+encodeURIComponent(user.id)+'/access',{method:'POST',body:{mode,...(mode==='through'?{through}:{})}});if(user.id===session.user.id){await refreshCurriculum();}await renderAdminUsers();setMessage('admin-message','关卡权限已更新。')},'user-detail-message')});scrollTo('#admin-user-detail');
}
function renderAdminSettings(settings){
 $('#admin-panel').innerHTML=`<div class="account-card wide"><h2>注册与关卡规则</h2><form id="admin-settings-form" class="account-form"><label>允许新注册的邮箱域名<textarea id="allowed-domains" rows="4" maxlength="2000" placeholder="每行一个，例如 example.com">${escapeHTML((settings.allowedDomains||[]).join('\n'))}</textarea></label><p class="muted-note">只接受精确域名，不接受通配符；留空将关闭普通账号的新注册。调整不取消已有账号的登录资格；不会把验证过的邮箱替换为其他地址。</p><label class="check-label"><input id="registration-enabled" type="checkbox" ${settings.registrationEnabled?'checked':''}><span>开放新账号注册（仍需邮箱验证）</span></label><label>逐关开放方式<select id="progression-mode"><option value="manual" ${settings.progressionMode==='manual'?'selected':''}>管理员手动开放</option><option value="sequential" ${settings.progressionMode==='sequential'?'selected':''}>完成前关后自动解锁</option></select></label><p class="muted-note">新账号默认开放第一关。自动模式下，完成前一关后开放下一关；管理员也可手动调整或一次开放全部关卡。</p><button id="save-settings" type="submit" class="button primary">保存注册设置</button><p id="settings-message" class="form-message" role="status"></p></form></div>`;
 $('#admin-settings-form').addEventListener('submit',event=>{event.preventDefault();action($('#save-settings'),async()=>{const allowedDomains=[...new Set($('#allowed-domains').value.split(/[\s,，;；]+/).map(x=>x.trim().toLowerCase()).filter(Boolean))];if(allowedDomains.some(d=>d.includes('@')||d.includes('*')||d.includes('/')))throw new Error('只填写完整邮箱域名，不带@、通配符或网址。');const registrationEnabled=$('#registration-enabled').checked,progressionMode=$('#progression-mode').value;if(!confirm('确认更新注册域名与关卡规则？已有账号记录不会删除。'))return;const result=await api('/api/admin/settings',{method:'PUT',body:{allowedDomains,registrationEnabled,progressionMode}});authConfig={...authConfig,...result};setMessage('settings-message','设置已保存。新注册将按这些规则校验。')},'settings-message')});
}
function bindInterface(){
 $('#close-safety').addEventListener('click',()=>closeDialog('safety-dialog'));$('#close-diagram').addEventListener('click',()=>closeDialog('diagram-dialog'));
 $$('dialog').forEach(d=>{d.addEventListener('cancel',event=>{event.preventDefault();closeDialog(d.id)});d.addEventListener('keydown',trapDialogFocus)});
 $('#map-current-month').addEventListener('click',()=>{mapMonth=String(monthForDay(state.day));$('#map-month').value=mapMonth;renderMap()});$('#map-all-year').addEventListener('click',()=>{mapMonth='all';$('#map-month').value='all';renderMap()});
 $('#day-prev').addEventListener('click',()=>chooseDay(state.day-1));$('#day-next').addEventListener('click',()=>chooseDay(state.day+1));$('#today-btn').addEventListener('click',()=>{chooseDay(recommendation());toast('每天一个主活动即可，按已开放的关卡慢慢探索。')});
 $$('.map-trigger').forEach(btn=>btn.addEventListener('click',()=>{if(!session||!activeChild||!experiments.length)return;if(['#dots','#journey','#sources'].includes(location.hash)){history.replaceState(history.state,'','#lab');syncView()}renderMap();openDialog('day-map')}));$('#close-map').addEventListener('click',()=>closeDialog('day-map'));$('#day-map').addEventListener('click',event=>{if(event.target===$('#day-map')){const r=$('#day-map').getBoundingClientRect();if(event.clientX<r.left||event.clientX>r.right||event.clientY<r.top||event.clientY>r.bottom)closeDialog('day-map')}});
 $$('[data-filter]').forEach(btn=>btn.addEventListener('click',()=>{filter=btn.dataset.filter;$$('[data-filter]').forEach(b=>b.setAttribute('aria-pressed',String(b===btn)));renderMap()}));$('#map-month').value=mapMonth;$('#map-month').addEventListener('change',event=>{mapMonth=event.target.value;renderMap()});$('#map-search').addEventListener('input',event=>{mapQuery=event.target.value;renderMap()});
 $('#child-switch').addEventListener('change',event=>selectChild(event.target.value));$('#retry-save').addEventListener('click',()=>{if(saveConflict){location.hash='#account';renderFamily()}else if(curriculumError&&!dirty)reloadDots();else flushSave()});
}
async function init(){
 bindInterface();clearStaleDialogState();syncView();try{authConfig=await api('/api/auth/config');let result;try{result=await api('/api/session')}catch(error){if(error.status!==401)throw error}if(result)await acceptSession(result);else{renderAuth();syncView()}}catch(error){$('#account-content').innerHTML='<div class="service-error"><h1 id="account-heading">家庭空间暂时没有连接</h1><p>'+escapeHTML(error.message)+'</p><p class="muted-note">为保护账号和儿童资料，连接失败时不会开放实验内容，也不会自动上传旧记录。</p><button id="retry-connection" class="button primary">重新连接</button></div>';$('#retry-connection').addEventListener('click',()=>location.reload());syncView()}
}
init();
function archivedChildrenHTML(){const list=children.filter(c=>c.archivedAt);return list.length?`<section class="account-section"><details><summary>已归档的儿童档案（${list.length}）</summary><p class="muted-note">归档保留记录。恢复后可继续探索，每个账号最多8个有效档案。</p>${list.map(c=>`<div class="form-actions"><span>${escapeHTML(c.nickname)} · ${escapeHTML(c.ageBand)}岁</span><button type="button" class="text-button" data-restore-child="${escapeHTML(c.id)}">恢复档案</button></div>`).join('')}<p id="restore-message" class="form-message" role="status"></p></details></section>`:''}
function bindRestoreChildren(){$$('[data-restore-child]').forEach(b=>b.addEventListener('click',()=>action(b,async()=>{const owner=session,epoch=contextEpoch,id=b.dataset.restoreChild;if(!await ensureSaved()||session!==owner||contextEpoch!==epoch)return;const result=await api('/api/children/'+encodeURIComponent(id)+'/restore',{method:'POST',body:{}});if(session!==owner||contextEpoch!==epoch)return;children=children.map(c=>c.id===result.child.id?result.child:c);await selectChild(result.child.id,{skipSave:true});location.hash='#lab';syncView()},'restore-message')))}
function setAuthBusy(busy){authBusy=busy;$$('#change-email,#resend-code,#auth-consent').forEach(b=>{b.disabled=busy||(b.id==='resend-code'&&Date.now()<resendAt)});if($('#auth-email'))$('#auth-email').readOnly=busy;if($('#auth-code'))$('#auth-code').readOnly=busy}

async function exclusiveFamilyMutation(work){
 if(familyMutationBusy)throw new Error('上一项家庭资料操作尚未完成，请稍候。');familyMutationBusy=true;
 const nodes=[...document.body.children].filter(n=>!['SCRIPT','STYLE'].includes(n.tagName)),prior=nodes.map(n=>n.inert);nodes.forEach(n=>n.inert=true);
 const notice=document.createElement('div');notice.className='family-operation-notice';notice.setAttribute('role','status');notice.textContent='正在保存家庭资料，请稍候。为避免记录冲突，暂时暂停编辑。';document.body.append(notice);
 try{return await work()}finally{familyMutationBusy=false;notice.remove();nodes.forEach((n,i)=>n.inert=prior[i])}
}
